/* xx_saf_extractor.c - search raw data for SAF.
 *
 * Scans for:
 *   53 41 46 2C 20 28 63 29 at +0  ("SAF, (c)")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the saf reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/saf/xx_saf.h"

static const uint8_t k_anchor0[] = { 0x53, 0x41, 0x46, 0x2C, 0x20, 0x28, 0x63, 0x29 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_SAF };

static Abstractformat *xx_saf_search_open(xx_io_device *window) {
    xx_saf *reader = xx_saf_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_saf_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_saf_free((xx_saf *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_saf_search_open, xx_saf_search_close
};

static xx_format_search_state *xx_saf_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_saf_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_saf_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_saf_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_saf_extractor = {
    xx_saf_create_format_search,
    xx_saf_get_current_format_info,
    xx_saf_format_search_find_next,
    xx_saf_free_format_search
};
